(6731661, 1007262, 124815, '<td valign="top">I assume this is one of Mark''s signature pics. Stands out in the context but it''s not enough considering it in itself. Too staged for a picture and less staged for a statement. It''s one of those instances in which the technicals should have been exceptional. Outside the challenge I would give a 4, here, a 6.</td>', 'I assume this is one of Mark''s signature pics. Stands out in the context but it''s not enough considering it in itself. Too staged for a picture and less staged for a statement. It''s one of those instances in which the technicals should have been exceptional. Outside the challenge I would give a 4, here, a 6.', '2012-04-04 00:19:16.000000', NULL, 1),
(6731960, 1007710, 134859, '<td valign="top">My only 10 in the challenge.  <br/>I love the composition, the color, the detail.  Everything is perfectly executed in this shot!  Well done</td>', 'My only 10 in the challenge.  I love the composition, the color, the detail.  Everything is perfectly executed in this shot!  Well done', '2012-04-04 09:07:38.000000', NULL, 1),
(6731961, 1007762, 134859, '<td valign="top">Beautiful shot!  Great detail.  The black and white is superb.  The dewdrops add that little extra something.  Very well done!  9</td>', 'Beautiful shot!  Great detail.  The black and white is superb.  The dewdrops add that little extra something.  Very well done!  9', '2012-04-04 09:08:08.000000', NULL, 1),
(6731963, 1007757, 134859, '<td valign="top">LOVE this.  It''s a wonderful shot.  The double corners is wonderfully composed.  And the look on her face is perfect.  9</td>', 'LOVE this.  It''s a wonderful shot.  The double corners is wonderfully composed.  And the look on her face is perfect.  9', '2012-04-04 09:08:36.000000', NULL, 1),
(6731965, 1006718, 134859, '<td valign="top">Beautiful char!  Love the clean, stark white background.  This is a wonderful shot.  9</td>', 'Beautiful char!  Love the clean, stark white background.  This is a wonderful shot.  9', '2012-04-04 09:09:00.000000', NULL, 1),
(6731967, 1007856, 134859, '<td valign="top">Beautiful colors in this shot.  Love the double corner (almost triple corners) used.  Beautifully composed.</td>', 'Beautiful colors in this shot.  Love the double corner (almost triple corners) used.  Beautifully composed.', '2012-04-04 09:09:35.000000', NULL, 1),
(6731970, 1006591, 134859, '<td valign="top">Great set up.  The lighting is a little bright on the pieces and corner, almost washing it out... BUT, being said, it also shows the detail in the board.  So it''s a 50/50 decision on whether I would tone down the lighting there, or keep it as is.  <br/>Love the concept here.</td>', 'Great set up.  The lighting is a little bright on the pieces and corner, almost washing it out... BUT, being said, it also shows the detail in the board.  So it''s a 50/50 decision on whether I would tone down the lighting there, or keep it as is.  Love the concept here.', '2012-04-04 09:11:41.000000', NULL, 1),
(6731971, 1007657, 134859, '<td valign="top">Beautiful shot.  Lovely detail and great lighting!  I love this.  Very well done.</td>', 'Beautiful shot.  Lovely detail and great lighting!  I love this.  Very well done.', '2012-04-04 09:11:56.000000', NULL, 1),
(6731972, 1006965, 134859, '<td valign="top">Awesome shot!  Love the pure amount of negative space in this picture.  Very well done</td>', 'Awesome shot!  Love the pure amount of negative space in this picture.  Very well done', '2012-04-04 09:12:21.000000', NULL, 1),
(6731973, 1007859, 134859, '<td valign="top">Beautiful.  Great colors, wonderful detail.  You''ve framed this spot on.  It''s a wonderful shot!</td>', 'Beautiful.  Great colors, wonderful detail.  You''ve framed this spot on.  It''s a wonderful shot!', '2012-04-04 09:12:44.000000', NULL, 1),
(6731974, 1007571, 134859, '<td valign="top">I like the two bottom corners being used for this challenge.  The shadows/darkness of the right side of the frame really make the woman walking through them stand out!  And the look on the other person''s face is almost as if she is trying to figure out who is coming out of the darkness.  <br/>Great detail!  Beautiful black and white.  Well done.</td>', 'I like the two bottom corners being used for this challenge.  The shadows/darkness of the right side of the frame really make the woman walking through them stand out!  And the look on the other person''s face is almost as if she is trying to figure out who is coming out of the darkness.  Great detail!  Beautiful black and white.  Well done.', '2012-04-04 09:13:51.000000', NULL, 1),
(6731975, 1007453, 134859, '<td valign="top">Beautiful black and white!  Love the detail in the dog''s fur.  This is a well done shot.</td>', 'Beautiful black and white!  Love the detail in the dog''s fur.  This is a well done shot.', '2012-04-04 09:14:07.000000', NULL, 1),
(6731977, 1007857, 134859, '<td valign="top">Another "leap day" attempt with the "corners" challenge.  <br/>I really like how this turned out.  It almost looks like he is flying, which is the point, I''m sure.  Great colors and detail.</td>', 'Another "leap day" attempt with the "corners" challenge.  I really like how this turned out.  It almost looks like he is flying, which is the point, I''m sure.  Great colors and detail.', '2012-04-04 09:15:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6731981, 1007887, 134859, '<td valign="top">Beautiful shot.  Love the background blur!  And the feather in his mouth is a wonderful capture.  If you could have positioned this a little more towards the top or bottom left corner and taken a few steps back (or zoomed out a little) it would have REALLY been placed in the corner.  <br/>Either way, this is a great shot!  Beautiful colors, lovely detail!  Nicely done.</td>', 'Beautiful shot.  Love the background blur!  And the feather in his mouth is a wonderful capture.  If you could have positioned this a little more towards the top or bottom left corner and taken a few steps back (or zoomed out a little) it would have REALLY been placed in the corner.  Either way, this is a great shot!  Beautiful colors, lovely detail!  Nicely done.', '2012-04-04 09:16:15.000000', NULL, 1),
(6731982, 1007785, 134859, '<td valign="top">Gorgeous shot!  I love the rolling waves, the colors, and the father and son in the bottom corner add that perfect detail.  This would be a great shot even if it wasn''t for the corner''s challenge!  Nicely executed!</td>', 'Gorgeous shot!  I love the rolling waves, the colors, and the father and son in the bottom corner add that perfect detail.  This would be a great shot even if it wasn''t for the corner''s challenge!  Nicely executed!', '2012-04-04 09:16:58.000000', NULL, 1),
(6731983, 1007529, 134859, '<td valign="top">Wonderful shot!  Love the pose, the detail, the black and white.  Great job placing him in the corner, it really works at the top corner of the photo!</td>', 'Wonderful shot!  Love the pose, the detail, the black and white.  Great job placing him in the corner, it really works at the top corner of the photo!', '2012-04-04 09:17:47.000000', NULL, 1),
(6731984, 1007619, 134859, '<td valign="top">I love the PP in this shot!  This is a very "grunge" looking picture.  Great use of composition here.  The guy is in the bottom right corner, and then you look to the top left corner where the street lights are... well done!  I think you''ve managed to shoot this challenge quite nicely!</td>', 'I love the PP in this shot!  This is a very "grunge" looking picture.  Great use of composition here.  The guy is in the bottom right corner, and then you look to the top left corner where the street lights are... well done!  I think you''ve managed to shoot this challenge quite nicely!', '2012-04-04 09:19:04.000000', NULL, 1),
(6731985, 1007230, 134859, '<td valign="top">Good shot.  The darkness in the foreground make you not even want to look in those corners, which makes you attention stay drawn to the top corners of the photo, where the action is at.  If you could have caught the dog looking at the camera, that would have been great.  But I like how his running in one direction, while the person on the board is going in the opposite direction.  Well done with this shot!</td>', 'Good shot.  The darkness in the foreground make you not even want to look in those corners, which makes you attention stay drawn to the top corners of the photo, where the action is at.  If you could have caught the dog looking at the camera, that would have been great.  But I like how his running in one direction, while the person on the board is going in the opposite direction.  Well done with this shot!', '2012-04-04 09:20:35.000000', NULL, 1),
(6732020, 1007901, 134859, '<td valign="top">Great use of all 4 corners.  The faded black middle (perhaps it''s lighting) is a little distracting... but overall, this is a great shot!</td>', 'Great use of all 4 corners.  The faded black middle (perhaps it''s lighting) is a little distracting... but overall, this is a great shot!', '2012-04-04 09:49:58.000000', NULL, 1),
