(6735982, 1007570, 11769, '<td valign="top">The post at the very edge of the frame and that gorgeous wall, Stunning. The mum, timeless and patient. She endures life''s pain with calm acceptance.</td>', 'The post at the very edge of the frame and that gorgeous wall, Stunning. The mum, timeless and patient. She endures life''s pain with calm acceptance.', '2012-04-08 10:40:29.000000', NULL, 1),
(6735987, 1007232, 11769, '<td valign="top">We have to keep believing, what else can we do. Love this.</td>', 'We have to keep believing, what else can we do. Love this.', '2012-04-08 10:43:25.000000', NULL, 1),
(6735988, 1007740, 143116, '<td valign="top">Intrigueing studio not short of inspiration</td>', 'Intrigueing studio not short of inspiration', '2012-04-08 10:43:43.000000', NULL, 1),
(6735991, 1007550, 11769, '<td valign="top">I have to look at this as a painter. I would paint this 20 feet wide so  standing back 30 feet or so it would look like this, Then as one approached they would realize the paint is slapped on thick and purposeful, abstract in nature. Great tonalities.</td>', 'I have to look at this as a painter. I would paint this 20 feet wide so  standing back 30 feet or so it would look like this, Then as one approached they would realize the paint is slapped on thick and purposeful, abstract in nature. Great tonalities.', '2012-04-08 10:51:13.000000', NULL, 1),
(6735992, 1006596, 11769, '<td valign="top">Wonderful shadows, color. Carrying coffee.</td>', 'Wonderful shadows, color. Carrying coffee.', '2012-04-08 10:56:12.000000', NULL, 1),
(6736001, 1007820, 8724, '<td valign="top">Is this Mayaguez, PR? Looking towards Añasco and Rincon? If it''s not, it looks a lot alike.</td>', 'Is this Mayaguez, PR? Looking towards Añasco and Rincon? If it''s not, it looks a lot alike.', '2012-04-08 11:20:11.000000', NULL, 1),
(6736021, 1007571, 50864, '<td valign="top">Fascinating image. One of my favorites.</td>', 'Fascinating image. One of my favorites.', '2012-04-08 11:56:57.000000', NULL, 1),
