(6736759, 1007861, 113900, '<td valign="top">Thanks Neat.</td>', 'Thanks Neat.', '2012-04-09 01:25:06.000000', NULL, 0),
(6736762, 1007736, 124815, '<td valign="top">So much power in this image and so many little things that trick the eyes. The smoke of the chimneys seems to be truly black while the  white foamy one looks like the breath of the mountains. And all the heavy machinery  rests on a a tiny rivulet of silvery water. beautiful.</td>', 'So much power in this image and so many little things that trick the eyes. The smoke of the chimneys seems to be truly black while the  white foamy one looks like the breath of the mountains. And all the heavy machinery  rests on a a tiny rivulet of silvery water. beautiful.', '2012-04-09 01:25:39.000000', NULL, 0),
(6736763, 1007248, 124815, '<td valign="top">Wonderful rhythm.</td>', 'Wonderful rhythm.', '2012-04-09 01:27:29.000000', NULL, 0),
