(6740301, 1007570, 97225, '<td valign="top">Congrats on the ribbon, Don. I''m sorry I didn''t get to viewing/voting so you got no contribution from me, but it is a darn fine image. I like the little stain on the wall behind the sheep - it looks like a shepherd.</td>', 'Congrats on the ribbon, Don. I''m sorry I didn''t get to viewing/voting so you got no contribution from me, but it is a darn fine image. I like the little stain on the wall behind the sheep - it looks like a shepherd.', '2012-04-13 02:19:36.000000', NULL, 0),
(6740402, 1007570, 28742, '<td valign="top">Congrats on your assimilation! :P heehee.</td>', 'Congrats on your assimilation! :P heehee.', '2012-04-13 04:25:03.000000', NULL, 0),
(6740527, 1007220, 100831, '<td valign="top">Your "frame" is an interesting choice. A hint of springtime.I</td>', 'Your "frame" is an interesting choice. A hint of springtime.I', '2012-04-13 09:53:54.000000', NULL, 0),
(6740541, 1007220, 38725, '<td valign="top">Nice minimalist shot, great use of negative space, not keen on the vignette but that''s just a personal opinion :)</td>', 'Nice minimalist shot, great use of negative space, not keen on the vignette but that''s just a personal opinion :)', '2012-04-13 10:05:02.000000', NULL, 0),
(6740657, 1007220, 104009, '<td valign="top">hmmm i think this may have suffered score-wise from being more on a "side" than a "corner".  the negative space is pleasing, not so sure about the vignette. i''d like to see this with a "blended" edge to the vignette.</td>', 'hmmm i think this may have suffered score-wise from being more on a "side" than a "corner".  the negative space is pleasing, not so sure about the vignette. i''d like to see this with a "blended" edge to the vignette.', '2012-04-13 12:22:29.000000', NULL, 0);
